import { ChangeDetectionStrategy, Component, effect, Input } from '@angular/core';

import { CommonModule } from '@angular/common';
import { TranslateModule, TranslateService } from '@ngx-translate/core';

import { TranslationService } from '../../../core/services/translation.service';
import { RouterModule } from '@angular/router';

@Component({
	selector: 'app-turnaround',
	standalone: true,
	imports: [CommonModule, TranslateModule,RouterModule],
	templateUrl: './turnaround.component.html',
	styleUrl: './turnaround.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
})
export class TurnaroundComponent {
	@Input() sectionKey = 'TURNAROUND.HOME';

	constructor(
		public translationService: TranslationService,
		public translate: TranslateService,
	) {
		effect(() => {
			this.translationService.currentLang();
		});
	}

	getIncludedKeys(): string[] {
		const included = this.translate.instant(`${this.sectionKey}.INCLUDED`);

		return included && typeof included === 'object' ? Object.keys(included) : [];
	}

	getQuotedKeys(): string[] {
		const quoted = this.translate.instant(`${this.sectionKey}.QUOTED`);

		return quoted && typeof quoted === 'object' ? Object.keys(quoted) : [];
	}
}
